{
  "css": "#rate-dialog { display: flex; flex-direction: column; gap: 32px; padding-top: 16px; }
#rate-dialog h1, #rate-dialog h2 { font-size: 22px; line-height: 1.5; font-weight: 700; }
.rate-trip { font-size: 14px; line-height: 1.5; color: var(--muted); margin-bottom: 16px; }
.rate-note { font-size: 14px; line-height: 1.5; color: var(--muted); margin-bottom: 16px; }
#rate-options { display: flex; flex-direction: column; gap: 8px; }
.rate-option { display: flex; align-items: flex-start; gap: 12px; padding: 16px; background-color: var(--quiet); border-radius: 8px; cursor: pointer; }
.rate-option input[type="radio"] { width: 20px; height: 20px; margin: 0; flex-shrink: 0; accent-color: var(--action); }
.rate-option label { flex: 1; min-width: 0; font-size: 16px; line-height: 1.5; font-weight: 500; color: var(--text); }
.rate-option input:checked + label { background-color: #fff; box-shadow: inset 2px 0 0 var(--action); }
.rate-text { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.rate-text [data-rate-name] { font-size: 16px; line-height: 1.5; font-weight: 600; color: var(--text); }
.rate-text [data-rate-policy] { font-size: 14px; line-height: 1.5; color: var(--muted); }
.rate-text [data-rate-nightly] { font-size: 14px; line-height: 1.5; color: var(--muted); }
.rate-text [data-rate-total] { font-size: 18px; line-height: 1.5; font-weight: 700; color: var(--text); }
#confirm-rate { width: 100%; margin-top: 24px; padding: 16px; background-color: var(--action); color: #fff; border: 0; border-radius: 8px; font-size: 16px; line-height: 1.5; font-weight: 600; min-height: 44px; cursor: pointer; }
#confirm-rate[disabled] { background-color: var(--quiet); color: var(--muted); cursor: not-allowed; pointer-events: none; }
#room-bottom { position: fixed; bottom: 0; left: 50%; transform: translateX(-50%); margin-inline: auto; width: 100%; max-width: 390px; z-index: 10; background-color: #fff; padding: 16px; padding-bottom: calc(16px + env(safe-area-inset-bottom)); }
.selected-room-summary { display: flex; flex-direction: column; gap: 4px; }
#selected-room-name { font-size: 14px; line-height: 1.5; font-weight: 500; color: var(--text); }
#selected-room-total { font-size: 18px; line-height: 1.5; font-weight: 700; color: var(--text); }
#continue-review { margin-top: 12px; width: 100%; padding: 16px; background-color: var(--action); color: #fff; border: 0; border-radius: 8px; font-size: 16px; line-height: 1.5; font-weight: 600; min-height: 44px; cursor: pointer; }
#review-view { display: flex; flex-direction: column; gap: 32px; padding-top: 16px; }
#review-view h1 { font-size: 22px; line-height: 1.5; font-weight: 700; color: var(--text); margin: 0; }
#review-view h2 { font-size: 18px; line-height: 1.5; font-weight: 600; color: var(--text); margin: 0; }
.review-stay { display: flex; flex-direction: row; gap: 12px; align-items: flex-start; }
.review-stay img { width: 120px; height: 80px; object-fit: cover; border-radius: 4px; max-width: 40%; flex-shrink: 0; }
.review-stay > div { flex: 1; min-width: 0; }
.review-stay p { font-size: 14px; line-height: 1.5; font-weight: 500; color: var(--text); margin: 0; }
#review-view dl { margin: 16px 0 0; display: flex; flex-direction: column; gap: 12px; }
#review-view dl > div { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 8px; }
#review-view dt { font-size: 16px; line-height: 1.5; font-weight: 500; color: var(--text); margin: 0; }
#review-view dd { margin: 0; font-size: 16px; line-height: 1.5; font-weight: 500; color: var(--text); }
.review-total { margin-top: 12px; }
.review-total dt, .review-total dd { font-size: 18px; line-height: 1.5; font-weight: 700; color: var(--text); }
.review-policy p { font-size: 16px; line-height: 1.5; font-weight: 500; color: var(--text); margin: 0; gap: 8px; }"
}
